import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Object3D } = ctx.THREE;
  const group = new Group();

  let glbAsset = null;
  let hoverTimeline = null;
  let clickTimeline = null;

  // Load GLB and build the divider
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    glbAsset = gltf;

    // Clone the scene from the GLB
    if (gltf.scene) {
      const mesh = gltf.scene.clone();
      group.add(mesh);

      // Store reference for interaction handlers
      group.userData.mesh = mesh;
    }
  });

  // Hover handler: rise-in preset (subtle 0.15 scene units)
  const onHover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  const onHoverOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: config.scenePosition?.[1] ?? 0.7,
      duration: 0.9,
      ease: 'power4.out',
      overwrite: 'auto'
    });
  };

  // Click handler: press-down effect + emit navigation
  const onClick = () => {
    if (clickTimeline) clickTimeline.kill();

    // Press down scale
    clickTimeline = gsap.timeline();
    clickTimeline.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out'
    }, 0);

    // Emit navigation event
    ctx.emit('navigate', { to: 'hub-home' });

    // Settle back to normal scale
    gsap.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out',
      delay: 0.12
    });
  };

  // Attach handlers to userData
  group.userData.handlers = {
    onHover,
    onHoverOut,
    onClick
  };

  // Apply scene position
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition[0],
      config.scenePosition[1],
      config.scenePosition[2]
    );
  }

  // Apply scene rotation
  if (config.sceneRotation) {
    group.rotation.order = 'YXZ';
    group.rotation.set(
      config.sceneRotation[0],
      config.sceneRotation[1],
      config.sceneRotation[2]
    );
  }

  // Apply scene scale
  if (config.sceneScale) {
    group.scale.set(
      config.sceneScale[0],
      config.sceneScale[1],
      config.sceneScale[2]
    );
  }

  // Cleanup function
  group.userData.cleanup = () => {
    if (hoverTimeline) {
      hoverTimeline.kill();
      hoverTimeline = null;
    }
    if (clickTimeline) {
      clickTimeline.kill();
      clickTimeline = null;
    }

    // Dispose of geometries and materials
    group.traverse((child) => {
      if (child.geometry) {
        child.geometry.dispose();
      }
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((mat) => mat.dispose());
        } else {
          child.material.dispose();
        }
      }
    });

    // Clear handlers
    group.userData.handlers = {};
  };

  return group;
}
